// Every lesson includes a concept, rules, a worked example, a misconception and a quick check.
const L=(intro,rules,example,steps,mistake,check,answer)=>({intro,rules,example,steps,mistake,check,answer});
const lessons={
'1-0':L('Число показывает, сколько предметов мы считаем. Чтобы сравнить две группы, можно соединить предметы в пары: где остались лишние, там больше. На числовом луче числа растут слева направо.', ['Следующее число на 1 больше предыдущего.','Предыдущее число на 1 меньше.','В числовом ряду каждое число занимает своё место.'], 'На полке 6 книг. Поставили ещё одну. Сколько стало?', ['Начинаем с числа 6.','Один шаг вправо по числовому лучу приводит к 7.','Значит, на полке 7 книг.'], 'Не начинай пересчитывать с нуля, если считаешь предметы: первый предмет — это один.', 'Какое число стоит между 7 и 9?',8),
'1-1':L('Сложение объединяет группы, а вычитание показывает, сколько осталось или насколько одна группа больше другой. Эти действия связаны: вычитанием можно проверить сложение.', ['Сложить — значит прибавить: 3 + 2 = 5.','Вычесть — значит убрать: 5 − 2 = 3.','Если a + b = c, то c − b = a.'], 'Было 8 кубиков. 3 убрали, потом 2 вернули. Сколько стало?', ['После первого действия осталось 8 − 3 = 5.','Возвращаем 2: 5 + 2 = 7.','Проверяем обратными действиями: 7 − 2 + 3 = 8.'], 'Слова «больше» и «меньше» — не команда автоматически прибавлять или вычитать. Сначала выясни, какое число неизвестно.', 'Какое число спрятано: 5 + □ = 12?',7),
'1-2':L('Фигура — это форма. У многоугольника есть стороны и вершины, а название часто помогает узнать их число. В логических задачах важно не угадывать по рисунку, а проверять, что изменилось.', ['У треугольника 3 стороны и 3 вершины.','У квадрата 4 равные стороны и 4 прямых угла.','Поворот фигуры не меняет число её сторон.'], 'Квадрат повернули и поставили на вершину. Сколько у него теперь сторон?', ['До поворота было 4 стороны.','Ни одна сторона не исчезла и не добавилась.','После поворота сторон по-прежнему 4.'], 'Квадрат, повёрнутый на угол, остаётся квадратом. Положение фигуры не определяет её свойства.', 'Сколько вершин у двух отдельных треугольников вместе?',6),
'2-0':L('Умножение — короткая запись сложения одинаковых слагаемых. Деление помогает разложить предметы поровну или узнать, сколько одинаковых групп получится.', ['3 × 4 = 4 + 4 + 4.','Проверяй деление умножением: 20 : 5 = 4, потому что 4 × 5 = 20.','В задачах с разными группами сначала выясни, одинаковы ли их размеры.'], '18 карандашей разложили поровну в 3 коробки. Сколько в каждой?', ['Нужно разделить 18 предметов на 3 равные группы.','18 : 3 = 6.','Проверка: в трёх коробках 3 × 6 = 18 карандашей.'], 'Не путай «разделить на 3 группы» и «разложить по 3»: ответы могут обозначать разные величины.', 'Сколько будет 7 × 3?',21),
'2-1':L('Величина описывает то, что можно измерить: длину, время, массу. Сравнивать и складывать величины удобно, когда они выражены в одинаковых единицах.', ['1 м = 100 см; 1 дм = 10 см.','1 час = 60 минут, а не 100.','Перед вычислением приведи величины к общим единицам.'], 'Сколько сантиметров в 1 м 25 см?', ['Один метр заменяем на 100 сантиметров.','Теперь единицы одинаковы: 100 см + 25 см.','Получаем 125 см.'], 'Время не записывается как обычная десятичная дробь: 1 час 30 минут — это полтора часа.', 'Сколько минут в двух часах?',120),
'2-2':L('Периметр — длина всей границы фигуры. Представь, что обводишь фигуру ниткой: длина этой нитки и есть периметр.', ['Сложи длины всех сторон.','У прямоугольника P = 2 × (a + b).','У квадрата P = 4 × a.'], 'У прямоугольника длина 6 см, ширина 2 см. Найди периметр.', ['У него две стороны по 6 см и две по 2 см.','P = 6 + 2 + 6 + 2.','Получаем 16 см.'], 'Площадь и периметр — разные величины. Периметр измеряют в сантиметрах, а не в квадратных сантиметрах.', 'Сторона квадрата 5 см. Чему равен периметр в см?',20),
'3-0':L('Выражение — запись вычислений. Порядок действий нужен, чтобы одна и та же запись всегда давала один результат. Скобки помогают явно выбрать, какое действие выполнить первым.', ['Сначала действия в скобках.','Затем умножение и деление слева направо.','Потом сложение и вычитание слева направо.'], 'Вычисли 30 − 12 : 3 + 2.', ['Сначала деление: 12 : 3 = 4.','Получаем 30 − 4 + 2.','Слева направо: 26 + 2 = 28.'], 'Умножение не всегда выполняется раньше деления: у них одинаковый приоритет, поэтому иди слева направо.', 'Вычисли 18 : 3 × 2.',12),
'3-1':L('Доля — одна из равных частей целого. Если разделить предмет на 4 равные части, одна часть называется четвертью. Чтобы сравнивать доли, важно брать одно и то же целое.', ['Найти половину — разделить на 2.','Найти треть — разделить на 3.','Если известна одна из n равных частей, умножь её на n, чтобы найти целое.'], 'Треть ленты имеет длину 8 см. Какова длина всей ленты?', ['Лента состоит из трёх одинаковых третей.','Каждая такая часть имеет длину 8 см.','Вся лента: 8 × 3 = 24 см.'], 'Половина большого пирога может быть больше целого маленького. Сравнивай части одного и того же целого.', 'Четверть числа равна 6. Чему равно число?',24),
'3-2':L('Площадь показывает, сколько единичных квадратов помещается внутри фигуры. В прямоугольнике клетки образуют одинаковые ряды, поэтому их можно посчитать умножением.', ['S прямоугольника = a × b.','S квадрата = a².','Если известны площадь и одна сторона, другую найди делением.'], 'Прямоугольник составлен из 5 рядов по 3 клетки. Какова его площадь?', ['В одном ряду 3 единичных квадрата.','Таких рядов 5: S = 5 × 3.','Площадь равна 15 квадратным единицам.'], 'Не складывай стороны для нахождения площади: это поможет с периметром, но не с числом клеток внутри.', 'Чему равна площадь квадрата со стороной 4 см в см²?',16),
'4-0':L('В десятичной записи значение цифры зависит от её места. Каждый следующий разряд слева в 10 раз крупнее предыдущего. При делении с остатком выделяют целые группы и то, что не вошло ни в одну из них.', ['Число можно разложить на разрядные слагаемые.','При делении a на b: a = bq + r.','Для положительного делителя остаток удовлетворяет 0 ≤ r < b.'], 'Раздели 53 на 7 с остатком.', ['Наибольшее кратное 7, не превышающее 53, — это 49.','53 = 7 × 7 + 4.','Частное 7, остаток 4. Он меньше делителя 7.'], 'Если остаток равен делителю или больше него, можно выделить ещё одну целую группу — деление не закончено.', 'Чему равен остаток от деления 46 на 6?',4),
'4-1':L('Скорость показывает расстояние за единицу времени. Если скорость постоянна, расстояние растёт равномерно. Для двух движущихся объектов удобно следить за расстоянием между ними.', ['s = v × t, t = s : v, v = s : t.','При движении навстречу скорости складываются.','При догонялках в одном направлении скорость сближения равна разности скоростей.'], 'Пешеход идёт 5 км/ч, велосипедист едет навстречу со скоростью 15 км/ч. Между ними 40 км.', ['За час расстояние сокращается на 5 + 15 = 20 км.','Время до встречи: 40 : 20.','Они встретятся через 2 часа.'], 'Согласуй единицы: скорость в км/ч требует времени в часах. 30 минут — это 0,5 часа.', 'Сколько км проедет велосипедист за 2 часа со скоростью 14 км/ч?',28),
'4-2':L('В дроби знаменатель показывает, на сколько равных частей разделили целое, а числитель — сколько таких частей взяли. Чтобы найти часть числа, сначала найди одну долю.', ['В дроби a/b число b — знаменатель, b ≠ 0.','a/b от N = N : b × a.','Если известна дробь от числа, сначала восстанови одну долю, затем всё число.'], 'Найди 2/3 от 27.', ['Знаменатель 3: делим целое на 3 равные части.','Одна треть: 27 : 3 = 9.','Две трети: 9 × 2 = 18.'], 'Знаменатель — число частей, а не размер каждой части. Чем больше равных частей, тем меньше каждая из них.', 'Найди 3/5 от 20.',12),
'5-0':L('Делитель числа делит его без остатка, а кратное получается умножением числа на целое. Простое число больше 1 и имеет ровно два положительных делителя: 1 и само себя.', ['Разложи число на простые множители.','НОД берёт общие простые множители в меньших степенях.','НОК берёт все нужные простые множители в наибольших степенях.'], 'Найди НОД и НОК чисел 18 и 24.', ['18 = 2 × 3², а 24 = 2³ × 3.','НОД = 2 × 3 = 6.','НОК = 2³ × 3² = 72. Проверка: 6 × 72 = 18 × 24.'], 'Число 1 не простое: у него только один положительный делитель. НОК не всегда равен произведению чисел.', 'Найди НОД чисел 15 и 25.',5),
'5-1':L('Дроби можно понимать как числа на числовой прямой. Равные дроби обозначают одну точку: умножение числителя и знаменателя на одно ненулевое число не меняет значение дроби.', ['Для сложения приведи дроби к общему знаменателю.','При умножении перемножь числители и знаменатели.','При делении умножь на обратную дробь; на ноль делить нельзя.'], 'Вычисли 1/3 + 1/4.', ['Знаменатели 3 и 4 удобно заменить на 12.','1/3 = 4/12, а 1/4 = 3/12.','4/12 + 3/12 = 7/12.'], 'Нельзя складывать знаменатели: 1/3 + 1/4 не равно 2/7. Сначала нужны части одного размера.', 'Вычисли 1/2 + 1/6. Запиши дробью.',2/3),
'5-2':L('Периметр измеряет границу, площадь — поверхность, объём — пространство внутри тела. Разные величины требуют разных единиц и формул.', ['P прямоугольника = 2(a + b), S = ab.','V прямоугольного параллелепипеда = abc.','У куба V = a³, площадь всей поверхности = 6a².'], 'Коробка имеет размеры 2 × 3 × 4 см. Найди объём.', ['В одном слое помещается 2 × 3 = 6 единичных кубиков.','Слоёв 4.','Всего 6 × 4 = 24 кубика, объём 24 см³.'], 'При увеличении всех рёбер в 2 раза объём увеличится в 8 раз, а площадь поверхности — в 4.', 'Чему равна площадь всей поверхности куба с ребром 2 см?',24),
'6-0':L('Отношение сравнивает величины делением. Процент — это одна сотая выбранного целого. Самое важное в процентной задаче — каждый раз понимать, что именно принято за 100%.', ['p% от A = A × p/100.','Если p% числа равны B, то число равно B : (p/100).','Повышение на p% умножает число на 1 + p/100; снижение — на 1 − p/100.'], 'Товар стоил 500 рублей. Цену снизили на 10%. Найди новую цену.', ['За 100% принимаем исходные 500 рублей.','После скидки осталось 90% цены.','500 × 0,9 = 450 рублей.'], 'При последовательных изменениях меняется база процента. Повышение на 10% и снижение на 10% не отменяют друг друга.', 'Найди 12% от 250.',30),
'6-1':L('Отрицательные числа лежат левее нуля. Модуль — расстояние от числа до нуля, поэтому он всегда неотрицателен. Противоположные числа имеют одинаковые модули и разные знаки.', ['При сложении разных знаков вычти меньший модуль из большего.','Произведение двух чисел одного знака положительно, разных знаков — отрицательно.','|x| = a при a > 0 имеет два решения: x = a и x = −a.'], 'Вычисли −8 − (−3).', ['Вычитание отрицательного числа заменяем прибавлением противоположного.','−8 − (−3) = −8 + 3.','На числовой прямой идём от −8 на 3 вправо: получаем −5.'], 'Минус перед скобками меняет знак каждого слагаемого: −(a − b) = −a + b.', 'Вычисли (−4) × (−6).',24),
'6-2':L('Комбинаторика помогает считать варианты без полного перебора. Если выбор проходит в несколько последовательных этапов, число вариантов каждого этапа обычно перемножают.', ['Правило произведения: m вариантов, затем n вариантов дают mn пар.','Без повторения после выбора элемента вариантов становится на один меньше.','Если порядок не важен, одинаковые перестановки нельзя считать разными.'], 'Есть 4 напитка и 3 десерта. Сколькими способами выбрать один напиток и один десерт?', ['Для первого напитка доступны 3 десерта.','То же верно для каждого из 4 напитков.','Всего 4 × 3 = 12 наборов.'], 'Пара «Аня и Борис» совпадает с парой «Борис и Аня», если выбирается команда, а не распределяются роли.', 'Сколько трёхзначных кодов из цифр 1, 2, 3 можно составить без повторений?',6),
'7-0':L('Уравнение — равенство с неизвестным. Его корень превращает равенство в верное числовое утверждение. Представь весы: одинаковое действие с обеими частями сохраняет равновесие.', ['Раскрой скобки и приведи подобные слагаемые.','Прибавлять и вычитать одно число можно из обеих частей.','Умножать и делить обе части можно на одно ненулевое число.'], 'Реши 2(x + 3) = 14.', ['Раскрываем скобки: 2x + 6 = 14.','Вычитаем 6 из обеих частей: 2x = 8.','Делим на 2: x = 4. Проверяем: 2 × (4 + 3) = 14.'], 'При «переносе» слагаемого знак меняется, потому что из обеих частей вычитают одно и то же. Не дели на выражение, которое может быть нулём.', 'Реши 5x − 4 = 16.',4),
'7-1':L('Степень с натуральным показателем — произведение одинаковых множителей. Буквенные выражения подчиняются тем же правилам, что и числа: формулы позволяют увидеть удобную структуру.', ['aᵐ × aⁿ = aᵐ⁺ⁿ, (aᵐ)ⁿ = aᵐⁿ.','aᵐ : aⁿ = aᵐ⁻ⁿ при a ≠ 0 и m > n.','a² − b² = (a − b)(a + b); (a + b)² = a² + 2ab + b².'], 'Вычисли 52² − 48² без длинного умножения.', ['Узнаём разность квадратов.','52² − 48² = (52 − 48)(52 + 48).','4 × 100 = 400.'], 'В общем случае (a + b)² не равно a² + b²: пропадает слагаемое 2ab. А −a² и (−a)² могут иметь разные знаки.', 'Вычисли 3² × 3³.',243),
'7-2':L('Треугольник задают три вершины и соединяющие их стороны. Свойства углов помогают находить неизвестное без измерений. Доказательство опирается на свойства, а не на вид рисунка.', ['Сумма внутренних углов треугольника — 180°.','В равнобедренном треугольнике углы при основании равны.','Внешний угол равен сумме двух внутренних, не смежных с ним.'], 'Углы при основании равнобедренного треугольника равны 65°. Найди угол при вершине.', ['Два равных угла дают 65° + 65° = 130°.','Сумма всех углов 180°.','Угол при вершине равен 180° − 130° = 50°.'], 'Равные стороны лежат напротив равных углов. Не выбирай равные углы только потому, что они похожи на рисунке.', 'Внешний угол 120°, один из двух несмежных внутренних — 45°. Найди другой.',75),
'8-0':L('Арифметический квадратный корень из a — неотрицательное число, квадрат которого равен a. В действительных числах он определён только при a ≥ 0.', ['√a ≥ 0 и (√a)² = a при a ≥ 0.','√(ab) = √a × √b при a, b ≥ 0.','√(x²) = |x|, а не всегда x.'], 'Упрости √72.', ['Находим внутри 72 полный квадрат: 72 = 36 × 2.','√72 = √36 × √2.','Получаем 6√2.'], 'Уравнение x² = 9 имеет корни ±3, но само выражение √9 равно только 3. Корень суммы обычно не равен сумме корней.', 'Вычисли √((−7)²).',7),
'8-1':L('Квадратное уравнение имеет вид ax² + bx + c = 0, где a ≠ 0. Дискриминант определяет число действительных корней; теорема Виета связывает корни с коэффициентами.', ['D = b² − 4ac. При D > 0 два корня, при D = 0 один, при D < 0 действительных корней нет.','x = (−b ± √D)/(2a) при D ≥ 0.','Если корни существуют, x₁ + x₂ = −b/a, x₁x₂ = c/a.'], 'Реши x² − 3x − 4 = 0.', ['D = (−3)² − 4 × 1 × (−4) = 25.','x₁ = (3 + 5)/2 = 4; x₂ = (3 − 5)/2 = −1.','Проверка по Виету: 4 + (−1) = 3, 4 × (−1) = −4.'], 'Знак перед b в формуле корней — минус. При отрицательном b число −b положительно.', 'Найди больший корень x² − 9 = 0.',3),
'8-2':L('Теорема Пифагора связывает стороны только прямоугольного треугольника. Гипотенуза лежит напротив прямого угла и является самой длинной стороной.', ['a² + b² = c², где a и b — катеты, c — гипотенуза.','Чтобы найти катет: a = √(c² − b²).','Если для наибольшей стороны c верно a² + b² = c², треугольник прямоугольный.'], 'Гипотенуза равна 10, один катет — 6. Найди второй катет.', ['Обозначаем неизвестный катет b.','b² = 10² − 6² = 100 − 36 = 64.','b = 8, потому что длина положительна.'], 'Нельзя применять формулу к произвольному треугольнику. Сначала найди или докажи наличие прямого угла.', 'Катеты равны 5 и 12. Найди гипотенузу.',13),
'9-0':L('Функция сопоставляет каждому допустимому аргументу ровно одно значение. График состоит из точек (x; f(x)). У квадратичной функции график — парабола, положение которой удобно изучать через вершину.', ['Для y = ax² + bx + c, a ≠ 0: x вершины = −b/(2a).','При a > 0 ветви вверх и есть минимум, при a < 0 — вниз и есть максимум.','Выделение полного квадрата показывает сдвиг параболы.'], 'Найди минимум функции y = x² − 4x + 7.', ['Выделяем квадрат: y = (x − 2)² + 3.','Квадрат неотрицателен при любом x.','Минимум равен 3 и достигается при x = 2.'], 'Абсцисса вершины — это x, а значение функции в вершине — y. Не подменяй один вопрос другим.', 'Найди наименьшее значение (x + 1)² + 4.',4),
'9-1':L('В арифметической прогрессии каждый следующий член получается прибавлением одного и того же числа d. В геометрической — умножением на постоянный знаменатель q.', ['aₙ = a₁ + (n − 1)d.','Sₙ арифметической прогрессии = n(a₁ + aₙ)/2.','bₙ = b₁qⁿ⁻¹; Sₙ = b₁(qⁿ − 1)/(q − 1) при q ≠ 1.'], 'Найди сумму первых 5 членов прогрессии 2, 5, 8, …', ['Разность d = 3. Пятый член a₅ = 2 + 4 × 3 = 14.','S₅ = 5(2 + 14)/2.','Получаем 40. Проверка: 2 + 5 + 8 + 11 + 14 = 40.'], 'От первого до n-го члена нужно n − 1 переходов. Поэтому в формуле не nd, а (n − 1)d.', 'Первый член 4, разность 5. Найди четвёртый член.',19),
'9-2':L('При равновероятных элементарных исходах вероятность события равна доле подходящих исходов. Сначала опиши весь набор исходов, а затем выбери нужные.', ['P(A) = число благоприятных исходов / число всех исходов.','Вероятность всегда от 0 до 1.','P(не A) = 1 − P(A). Для независимых событий вероятности перемножаются.'], 'Из мешка с 3 красными и 2 синими шарами достают один шар. Какова вероятность синего?', ['Всего 3 + 2 = 5 равновероятных вариантов выбора шара.','Подходящих синих шаров 2.','P = 2/5 = 0,4.'], 'Суммы двух кубиков не равновероятны: сумму 7 дают больше пар, чем сумму 2. Считай пары граней, а не возможные суммы.', 'Какова вероятность числа больше 4 на стандартном кубике?',1/3),
'10-0':L('На единичной окружности cos α — горизонтальная координата точки, а sin α — вертикальная. Этот смысл объясняет знаки, периодичность и основное тождество.', ['sin² α + cos² α = 1.','sin 2α = 2 sin α cos α; cos 2α = cos² α − sin² α.','sin(90° − α) = cos α. Всегда проверяй, в градусах или радианах дан угол.'], 'Известно cos α = 12/13, угол α острый. Найди sin α.', ['sin² α = 1 − (12/13)² = 25/169.','Так как угол острый, sin α положителен.','sin α = 5/13.'], 'Из sin² α = 1/4 нельзя без сведений об угле выбрать только +1/2. Знак зависит от четверти.', 'Вычисли sin² 40° + cos² 40°.',1),
'10-1':L('Логарифм отвечает на вопрос: в какую степень надо возвести основание, чтобы получить число? Показательные и логарифмические выражения — два языка для одного отношения.', ['logₐ b = c означает aᶜ = b; a > 0, a ≠ 1, b > 0.','logₐ(xy) = logₐ x + logₐ y при x, y > 0.','logₐ x = ln x / ln a; logₐ(xᵏ) = k logₐ x при x > 0.'], 'Реши log₂(x − 1) = 3.', ['Область определения: x − 1 > 0, то есть x > 1.','По определению x − 1 = 2³ = 8.','x = 9. Число удовлетворяет условию x > 1.'], 'Логарифм суммы не равен сумме логарифмов. Перед преобразованиями проверь положительность аргументов.', 'Вычисли log₃ 81.',4),
'10-2':L('Стереометрия изучает фигуры в пространстве. Чертёж передаёт объём условно, поэтому прямые углы и равенства нужно устанавливать из условий. Часто пространственную задачу сводят к плоскому сечению.', ['Объём призмы V = S основания × h.','Объём пирамиды V = S основания × h / 3.','У куба d = a√3; у прямоугольного параллелепипеда d² = a² + b² + c².'], 'Найди пространственную диагональ коробки со сторонами 2, 3 и 6.', ['Диагональ основания имеет квадрат 2² + 3² = 13.','Добавляем квадрат высоты: d² = 13 + 6² = 49.','Диагональ d = 7.'], 'Высота — перпендикуляр к плоскости основания. Наклонное боковое ребро не всегда является высотой.', 'Объём пирамиды с площадью основания 18 и высотой 5 равен…',30),
'11-0':L('Производная описывает мгновенную скорость изменения функции и наклон касательной. Её знак помогает понять, где функция растёт или убывает, а смена знака — где расположен экстремум.', ['(xⁿ)′ = nxⁿ⁻¹; (f + g)′ = f′ + g′.','При f′ > 0 функция возрастает, при f′ < 0 убывает на интервале.','Для глобального экстремума на отрезке проверь критические точки внутри и оба конца.'], 'Найди минимум f(x) = x² − 6x + 10.', ['f′(x) = 2x − 6. Производная равна нулю при x = 3.','Левее 3 производная отрицательна, правее — положительна. Это минимум.','f(3) = 9 − 18 + 10 = 1.'], 'Равенство f′(x) = 0 само по себе не доказывает экстремум: у x³ в нуле экстремума нет. Проверь знак производной.', 'Найди производную x² в точке x = 5.',10),
'11-1':L('Первообразная F функции f удовлетворяет F′ = f. Определённый интеграл суммирует малые изменения и вычисляется через первообразную. Геометрическая площадь требует учитывать знак функции.', ['∫ от a до b f(x) dx = F(b) − F(a).','Первообразная xⁿ при n ≠ −1: xⁿ⁺¹/(n + 1) + C на подходящем интервале.','Площадь между графиками — интеграл верхней функции минус нижняя; при смене порядка разбей отрезок.'], 'Вычисли интеграл 3x² от 1 до 2.', ['Первообразная 3x² — это x³.','Подставляем пределы: F(2) − F(1).','2³ − 1³ = 8 − 1 = 7.'], 'Интеграл может быть отрицательным, площадь — нет. При вычислении площади частей ниже оси нужен модуль или разбиение.', 'Вычисли интеграл функции 2 от 1 до 4.',6),
'11-2':L('Сочетания считают неупорядоченные наборы, а вероятность связывает подсчёт вариантов со случайным выбором. Для «хотя бы одного» часто проще посчитать противоположное событие.', ['C(n,k) = n! / (k!(n − k)!) при 0 ≤ k ≤ n.','При независимых испытаниях P всех событий равно произведению их вероятностей.','Вероятность хотя бы одного успеха в n независимых испытаниях: 1 − (1 − p)ⁿ.'], 'Четыре раза бросают монету. Какова вероятность хотя бы одного орла?', ['Противоположное событие — четыре решки.','Его вероятность (1/2)⁴ = 1/16.','Искомая вероятность 1 − 1/16 = 15/16.'], 'При выборе без возвращения испытания обычно зависимы: после первого выбора меняются и состав набора, и число объектов.', 'Сколькими способами можно выбрать 3 человек из 6?',20)
};
